# ------------------------------------------------------------------ canvas --
class Canvas:
    def __init__(self, w=W, h=H, bg=CREAM):
        self.w, self.h = w, h
        self.px = bytearray(bg * (w * h))

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.px[i], self.px[i + 1], self.px[i + 2] = c

    def fill_rect(self, x0, y0, x1, y1, c):
        x0 = max(0, x0); y0 = max(0, y0)
        x1 = min(self.w, x1); y1 = min(self.h, y1)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(c) * (x1 - x0)
        for y in range(y0, y1):
            i = (y * self.w + x0) * 3
            self.px[i:i + len(row)] = row

    def hline(self, x0, x1, y, c):
        if 0 <= y < self.h:
            for x in range(max(0, x0), min(self.w, x1)):
                self.set(x, y, c)

    def vline(self, x, y0, y1, c):
        for y in range(max(0, y0), min(self.h, y1)):
            self.set(x, y, c)

    def rect(self, x0, y0, x1, y1, c, t=1):
        for k in range(t):
            self.hline(x0, x1, y0 + k, c)
            self.hline(x0, x1, y1 - 1 - k, c)
            self.vline(x0 + k, y0, y1, c)
            self.vline(x1 - 1 - k, y0, y1, c)

    def line(self, x0, y0, x1, y1, c):
        dx = abs(x1 - x0); dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1; sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            self.set(x0, y0, c)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy; x0 += sx
            if e2 <= dx:
                err += dx; y0 += sy

    def disc(self, cx, cy, r, c):
        for y in range(cy - r, cy + r + 1):
            dy = y - cy
            dx = int(math.sqrt(max(0, r * r - dy * dy)))
            self.hline(cx - dx, cx + dx + 1, y, c)

    def ring(self, cx, cy, r, c, t=1):
        for k in range(t):
            rr = r - k
            for y in range(cy - rr, cy + rr + 1):
                dy = y - cy
                dx = int(math.sqrt(max(0, rr * rr - dy * dy)))
                self.set(cx - dx, y, c); self.set(cx + dx, y, c)
            for x in range(cx - rr, cx + rr + 1):
                dx = x - cx
                dy = int(math.sqrt(max(0, rr * rr - dx * dx)))
                self.set(x, cy - dy, c); self.set(x, cy + dy, c)

    def poly_fill(self, pts, c):
        # scanline fill, even-odd
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(self.h, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]; x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    x = x0 + (y - y0) * (x1 - x0) / (y1 - y0)
                    xs.append(x)
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                self.hline(int(math.ceil(xs[k])), int(math.floor(xs[k + 1])) + 1, y, c)


# ------------------------------------------------------------- text helpers -
def glyph(font, ch):
    f = FONTS[font]
    if ch in f:
        return f[ch]
    return f["?"]

def text_width(font, s):
    return sum(glyph(font, ch)[0] for ch in s)

def draw_text(cv, font, x, y_top, s, c):
    cx = x
    for ch in s:
        adv, dx, dy, w, h, rows = glyph(font, ch)
        if w and h:
            data = bytes.fromhex(rows)
            stride = (w + 7) // 8
            for yy in range(h):
                for xx in range(w):
                    if data[yy * stride + xx // 8] & (0x80 >> (xx % 8)):
                        cv.set(cx + dx + xx, y_top + dy + yy, c)
        cx += adv
    return cx

def draw_text_centred(cv, font, cx, y_top, s, c):
    draw_text(cv, font, cx - text_width(font, s) // 2, y_top, s, c)

def wrap(font, s, width):
    """Greedy word wrap; raises if any single word cannot fit (fail loud)."""
    words = s.split(" ")
    lines, cur = [], ""
    for wd in words:
        if text_width(font, wd) > width:
            raise AssertionError("word too wide for budget: %r in %s" % (wd, font))
        trial = (cur + " " + wd).strip()
        if text_width(font, trial) <= width:
            cur = trial
        else:
            lines.append(cur)
            cur = wd
    if cur:
        lines.append(cur)
    return lines

def draw_wrapped(cv, font, x, y_top, s, width, line_h, c, max_lines=None):
    lines = wrap(font, s, width)
    if max_lines is not None:
        assert len(lines) <= max_lines, "text needs %d lines, max %d: %r" % (len(lines), max_lines, s)
    for i, ln in enumerate(lines):
        draw_text(cv, font, x, y_top + i * line_h, ln, c)
    return y_top + len(lines) * line_h


# ------------------------------------------------------------------ PNG ------
def write_png(cv, path):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 6)

    def chunk(tag, data):
        out = struct.pack(">I", len(data)) + tag + data
        return out + struct.pack(">I", binascii.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", comp) + chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)
    return png

