def point_in_poly(lon, lat, poly):
    inside = False
    n = len(poly)
    for i in range(n):
        x0, y0 = poly[i]
        x1, y1 = poly[(i + 1) % n]
        if (y0 > lat) != (y1 > lat):
            xin = x0 + (lat - y0) * (x1 - x0) / (y1 - y0)
            if lon < xin:
                inside = not inside
    return inside


def on_land(lon, lat):
    return any(point_in_poly(lon, lat, p) for p in LAND_POLYS)


# map rect (set by layout; also used by pin projection)
MAP_X0, MAP_X1 = 12, 702
MAP_Y0, MAP_Y1 = 650, 800
LON0, LON1 = -170.0, 190.0
LAT0, LAT1 = -60.0, 84.0


def project(lon, lat):
    x = MAP_X0 + (lon - LON0) / (LON1 - LON0) * (MAP_X1 - MAP_X0)
    y = MAP_Y1 - (lat - LAT0) / (LAT1 - LAT0) * (MAP_Y1 - MAP_Y0)
    return int(round(x)), int(round(y))


