def sky_bands(cv, x0, y0, w, h, top, bottom):
    for i in range(h):
        t = i / max(1, h - 1)
        c = tuple(int(top[k] + (bottom[k] - top[k]) * t) for k in range(3))
        cv.hline(x0, x0 + w, y0 + i, c)


def draw_flag(cv, x, y, w, h, kind):
    # tiny flags: us / cn / ru / jp / in / au
    if kind == "us":
        for i in range(7):
            cv.fill_rect(x, y + i * h // 7, x + w, y + (i + 1) * h // 7,
                         (178, 34, 52) if i % 2 == 0 else WHITE)
        cv.fill_rect(x, y, x + w // 2, y + h // 2, (29, 78, 158))
    elif kind == "cn":
        cv.fill_rect(x, y, x + w, y + h, (222, 41, 16))
        cv.disc(x + 3, y + 3, 1, (255, 222, 0))
    elif kind == "ru":
        cv.fill_rect(x, y, x + w, y + h // 3, WHITE)
        cv.fill_rect(x, y + h // 3, x + w, y + 2 * h // 3, (29, 78, 158))
        cv.fill_rect(x, y + 2 * h // 3, x + w, y + h, (178, 34, 52))
    elif kind == "jp":
        cv.fill_rect(x, y, x + w, y + h, WHITE)
        cv.disc(x + w // 2, y + h // 2, h // 4, (188, 0, 45))
    elif kind == "in":
        cv.fill_rect(x, y, x + w, y + h // 3, (255, 153, 51))
        cv.fill_rect(x, y + h // 3, x + w, y + 2 * h // 3, WHITE)
        cv.fill_rect(x, y + 2 * h // 3, x + w, y + h, (19, 136, 8))
    elif kind == "au":
        cv.fill_rect(x, y, x + w, y + h, (29, 78, 158))
        cv.disc(x + w // 2, y + h // 2, 2, WHITE)


