def scene_antchart(cv, x0, y0, w, h):
    cv.fill_rect(x0, y0, x0 + w, y0 + h, (10, 58, 58))
    for gy in range(y0 + 12, y0 + h, 14):
        cv.hline(x0 + 4, x0 + w - 4, gy, (30, 90, 90))
    pts = []
    vals = [14, 20, 18, 26, 24, 34, 30, 42, 40, 52, 58]
    for i, v in enumerate(vals):
        px = x0 + 14 + i * (w - 28) // 10
        py = y0 + h - 10 - v
        pts.append((px, py))
    for i in range(len(pts) - 1):
        cv.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], (255, 214, 130))
        cv.line(pts[i][0], pts[i][1] + 1, pts[i + 1][0], pts[i + 1][1] + 1, (255, 214, 130))
    for (px, py) in pts:
        cv.disc(px, py, 2, (255, 214, 130))
    for i in range(6):
        bx = x0 + 20 + i * 46
        bh = [10, 16, 12, 22, 18, 28][i]
        cv.fill_rect(bx, y0 + h - 8 - bh, bx + 12, y0 + h - 8,
                     (20, 140, 120) if i % 2 == 0 else (200, 60, 60))
    draw_text(cv, "SANSB10", x0 + 8, y0 + 4, "ANT", WHITE)
    draw_text(cv, "SANSB10", x0 + w - 44, y0 + 4, "$83", (255, 214, 130))


