def tile_scene(cv, kind, x0, y0, w, h):
    # small iconic bands, 24px tall
    rng = random.Random(SEED + 7)
    if kind == "court":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (226, 220, 200))
        cv.fill_rect(x0 + 8, y0 + 4, x0 + w - 8, y0 + 7, NAVY)
        for cx in range(x0 + 16, x0 + w - 12, 22):
            cv.fill_rect(cx, y0 + 8, cx + 5, y0 + h - 4, NAVY)
        cv.fill_rect(x0 + 8, y0 + h - 4, x0 + w - 8, y0 + h - 1, NAVY)
        cv.disc(x0 + w // 2, y0 + 12, 3, DARKGOLD)
    elif kind == "voyager":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (16, 22, 48))
        for _ in range(14):
            cv.set(x0 + rng.randrange(w), y0 + rng.randrange(h), WHITE)
        cv.disc(x0 + int(w * 0.72), y0 + 8, 5, (255, 224, 150))
        cv.line(x0 + 8, y0 + h - 5, x0 + int(w * 0.6), y0 + 10, (255, 214, 130))
        cv.disc(x0 + int(w * 0.6), y0 + 10, 2, (255, 214, 130))
    elif kind == "cop":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (30, 110, 80))
        cv.disc(x0 + int(w * 0.5), y0 + 12, 8, (120, 200, 140))
        cv.disc(x0 + int(w * 0.5), y0 + 12, 5, (30, 110, 80))
        cv.hline(x0 + 8, x0 + w - 8, y0 + h - 5, (255, 214, 130))
    elif kind == "cyclone":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (40, 90, 130))
        for r in (3, 6, 9):
            cv.ring(x0 + w // 2, y0 + h // 2, r, WHITE, 1)
        cv.disc(x0 + w // 2, y0 + h // 2, 2, CHIPRED)
    elif kind == "bridge":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (210, 225, 235))
        cv.fill_rect(x0, y0 + 8, x0 + w, y0 + 11, INK)
        cv.line(x0 + 10, y0 + 8, x0 + w // 2, y0 + h - 6, INK)
        cv.line(x0 + w - 10, y0 + 8, x0 + w // 2, y0 + h - 6, INK)
        cv.fill_rect(x0 + w // 2 - 14, y0 + h - 8, x0 + w // 2 + 14, y0 + h - 5, CHIPRED)
    elif kind == "vangogh":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (20, 40, 110))
        cv.rect(x0 + 14, y0 + 3, x0 + w - 14, y0 + h - 3, DARKGOLD, 2)
        cv.disc(x0 + w // 2, y0 + 11, 5, (255, 214, 60))
        cv.disc(x0 + w // 2 - 12, y0 + 15, 3, (255, 214, 60))
        cv.disc(x0 + w // 2 + 12, y0 + 15, 3, (255, 214, 60))
    elif kind == "base":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (200, 200, 190))
        cv.fill_rect(x0 + 12, y0 + 8, x0 + w - 12, y0 + h - 4, (90, 90, 85))
        cv.fill_rect(x0 + w // 2 - 2, y0 + 2, x0 + w // 2 + 2, y0 + 8, INK)
        draw_flag(cv, x0 + w // 2 + 3, y0 + 2, 12, 7, "us")
    elif kind == "flood":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (70, 120, 160))
        for yy in (8, 14, 20):
            for xx in range(x0 + 4, x0 + w - 4, 16):
                cv.hline(xx, xx + 10, y0 + yy, WHITE)
        cv.disc(x0 + w - 16, y0 + 6, 4, (255, 224, 150))
    elif kind == "canyon":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (150, 90, 60))
        for i, cc in enumerate([(200, 140, 90), (170, 110, 70), (140, 85, 55), (110, 65, 45)]):
            cv.fill_rect(x0, y0 + i * 6, x0 + w, y0 + i * 6 + 6, cc)
    elif kind == "capitol":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (226, 220, 200))
        cv.fill_rect(x0 + 10, y0 + 14, x0 + w - 10, y0 + h - 4, WHITE)
        cv.disc(x0 + w // 2, y0 + 13, 6, WHITE)
        cv.fill_rect(x0 + w // 2 - 1, y0 + 4, x0 + w // 2 + 1, y0 + 8, INK)
    elif kind == "shield":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (20, 33, 61))
        cv.disc(x0 + w // 2, y0 + 12, 8, (255, 214, 130))
        cv.disc(x0 + w // 2, y0 + 12, 5, NAVY)
        draw_text(cv, "SANSB8", x0 + w // 2 - 3, y0 + 9, "!", (255, 214, 130))
    elif kind == "seizure":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (240, 235, 220))
        for i, xx in enumerate(range(x0 + 10, x0 + w - 16, 24)):
            cv.fill_rect(xx, y0 + 8, xx + 16, y0 + 14, WHITE if i % 2 else CHIPRED)
            cv.rect(xx, y0 + 8, xx + 16, y0 + 14, INK, 1)
    elif kind == "flags2":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (226, 220, 200))
        draw_flag(cv, x0 + 18, y0 + 5, 22, 13, "in")
        draw_flag(cv, x0 + w - 40, y0 + 5, 22, 13, "jp")
    elif kind == "tanker":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (200, 220, 230))
        cv.fill_rect(x0 + 10, y0 + 12, x0 + w - 10, y0 + 19, (60, 60, 60))
        cv.fill_rect(x0 + w // 2, y0 + 6, x0 + w // 2 + 4, y0 + 12, (60, 60, 60))
        cv.hline(x0 + 4, x0 + w - 4, y0 + h - 4, (40, 90, 130))
    elif kind == "document":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (240, 235, 220))
        cv.rect(x0 + 14, y0 + 3, x0 + w - 30, y0 + h - 3, INK, 1)
        for yy in (8, 13, 18):
            cv.hline(x0 + 18, x0 + w - 36, y0 + yy, INK)
        cv.disc(x0 + w - 22, y0 + 12, 5, DARKGREEN)
    elif kind == "tower":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (210, 225, 235))
        cv.line(x0 + w // 2, y0 + 3, x0 + w // 2 - 12, y0 + h - 3, INK)
        cv.line(x0 + w // 2, y0 + 3, x0 + w // 2 + 12, y0 + h - 3, INK)
        cv.hline(x0 + w // 2 - 8, x0 + w // 2 + 8, y0 + 14, INK)
    elif kind == "sanction":
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (240, 235, 220))
        cv.disc(x0 + w // 2, y0 + 12, 8, CHIPRED)
        cv.disc(x0 + w // 2, y0 + 12, 5, WHITE)
        cv.line(x0 + w // 2 - 6, y0 + 6, x0 + w // 2 + 6, y0 + 18, CHIPRED)
    else:
        cv.fill_rect(x0, y0, x0 + w, y0 + h, (200, 200, 190))

# ------------------------------------------------------------------ layout --
MX0, MX1 = 12, 1012  # content margins
CW = MX1 - MX0       # 1000


def region_sums():
    sums = {c: 0 for c, _, _ in REGION_BAR}
    for it in LEADS + TILES:
        sums[it["region"]] += 1
    for (_, r, _, _, _) in BRIEFS:
        sums[r] += 1
    return sums


def check_story_counts():
    assert len(LEADS) == 3, len(LEADS)
    assert len(TILES) == 17, len(TILES)
    assert len(BRIEFS) == 30, len(BRIEFS)
    assert [it["n"] for it in LEADS + TILES] == list(range(1, 21))
    assert [b[0] for b in BRIEFS] == list(range(21, 51))
    sums = region_sums()
    assert sum(sums.values()) == 50, sums
    return sums


def check_pins_on_land():
    bad = []
    for it in LEADS + TILES:
        if not on_land(*it["pin"]):
            bad.append((it["n"], it["place"], it["pin"]))
    assert not bad, "pins not on land: %r" % (bad,)


def draw_chip(cv, cx, cy, r, fill, label, font="SANSB10"):
    cv.disc(cx, cy, r + 2, INK)
    cv.disc(cx, cy, r + 1, WHITE)
    cv.disc(cx, cy, r, fill)
    draw_text_centred(cv, font, cx, cy - 5, label, WHITE)


def draw_masthead(cv):
    draw_text(cv, "SANSB10", MX0, 10, "THE WORLD IN ONE DAY", RED)
    right = "THURSDAY'S NEWS \u00b7 ONE PAGE \u00b7 50 STORIES"
    draw_text(cv, "SANSB10", MX1 - text_width("SANSB10", right), 10, right, INK)
    title = "THURSDAY 19 NOVEMBER 2026"
    font = "TITLE46"
    if text_width(font, title) > CW:  # masthead fit loop: shrink only if it overflows
        font = "TITLE38"
    draw_text(cv, font, MX0, 24, title, INK)
    draw_text(cv, "BODY11", MX0, 72,
              "Three leaders meet in Shenzhen \u00b7 A court rules on Myanmar \u00b7 The biggest IPO ever debuts", RED)
    draw_text(cv, "SANS10", MX0, 86,
              COVERAGE + " \u2014 THE DAY IS IN PROGRESS \u00b7 ALL TIMES UTC UNLESS STATED \u00b7 COUNTS FROM THIS PAGE", INK)
    cv.fill_rect(MX0, 98, MX1, 100, INK)


def draw_region_bar(cv, sums):
    y0, y1 = 104, 122
    x = MX0
    total = sum(sums.values())
    widths = {}
    acc = 0
    for code, _, _ in REGION_BAR:
        w = int(round(sums[code] / total * CW))
        widths[code] = w
        acc += w
    widths["GL"] += CW - acc  # absorb rounding so the bar is exactly CW wide
    for code, fill, tcol in REGION_BAR:
        w = widths[code]
        cv.fill_rect(x, y0, x + w, y1, fill)
        label = "%s %d" % (code, sums[code])
        draw_text_centred(cv, "KICK9", x + w // 2, y0 + 5, label, tcol)
        x += w
    assert x == MX1, x


def draw_stat_strip(cv):
    y0 = 126
    cell_w, gap = 142, 1
    x = MX0
    for i, (num, cap) in enumerate(STATS):
        draw_text(cv, "LEAD21", x + 4, y0 + 2, num, RED)
        draw_wrapped(cv, "SANSB8", x + 4, y0 + 22, cap, cell_w - 8, 9, MUTED, max_lines=2)
        x += cell_w + gap
        if i < len(STATS) - 1:
            cv.vline(x - 1, y0 + 2, y0 + 38, MUTED)
    cv.hline(MX0, MX1, 168, INK)
    # FAIL LOUD (revise-2 guard): stat-strip caption ink must stay clear
    # of the lead-scene panels below. Captions are drawn with SANSB8 at
    # y0+22, line height 9, max 2 lines; a glyph's lowest ink row is
    # line_top + dy + h (exclusive bottom). Measured today: worst ink
    # ends at y=166, lead panels start at y=172. If the captions move
    # down or the panels move up, fail here instead of shipping clipped
    # captions (the revise-1 defect: the y=168 rule sliced line-2 ink).
    panel_top = 172  # must match the y passed to draw_lead() in build()
    ink_bottom = 0
    for _num, cap in STATS:
        lines = wrap("SANSB8", cap, cell_w - 8)
        last_top = y0 + 22 + (len(lines) - 1) * 9
        for ch in lines[-1]:
            _adv, _dx, dy, w, h, _rows = glyph("SANSB8", ch)
            if w and h:
                ink_bottom = max(ink_bottom, last_top + dy + h)
    assert ink_bottom < 168, \
        "stat-strip caption ink reaches y=%d, rule at y=168" % ink_bottom
    assert ink_bottom < panel_top, \
        "stat-strip caption ink reaches y=%d, lead panels start y=%d" % (ink_bottom, panel_top)


def draw_lead(cv, it, x, y, w, idx):
    # panel 172..330 (158 tall): scene 72, kicker, headline 2 lines, body 2 lines
    cv.fill_rect(x, y, x + w, y + 158, PAPER)
