    draw_lead_scene(cv, it["scene"], x + 1, y + 1, w - 2, 70)
    draw_chip(cv, x + 17, y + 17, 9, PRIMARY_DOTS[idx], str(it["n"]))
    draw_text(cv, "KICK9", x + 6, y + 74, "%d \u00b7 %s" % (it["n"], it["kicker"]), RED)
    draw_wrapped(cv, "LEAD21", x + 6, y + 86, it["head"], w - 12, 21, INK, max_lines=2)
    draw_wrapped(cv, "BODY11", x + 6, y + 130, it["body"], w - 12, 12, INK, max_lines=2)


